"use client";

import { useState } from "react";
import { motion } from "motion/react";
import { Lock, User, ArrowRight } from "lucide-react";

export default function AdminPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleLogin = (event: React.FormEvent) => {
    event.preventDefault();

    if (
      username === "admin" &&
      password === "change-moi"
    ) {
      setError("");

      // Pour l'instant, on affiche simplement le succès.
      // La vraie session sécurisée viendra juste après.
      alert("Connexion réussie");
    } else {
      setError("Identifiant ou mot de passe incorrect.");
    }
  };

  return (
    <main className="min-h-screen bg-[#050505] text-white">
      <div className="flex min-h-screen items-center justify-center px-5">

        <motion.div
          initial={{
            opacity: 0,
            y: 20,
            scale: 0.97,
          }}
          animate={{
            opacity: 1,
            y: 0,
            scale: 1,
          }}
          transition={{
            duration: 0.5,
            ease: "easeOut",
          }}
          className="w-full max-w-md"
        >

          {/* Logo / titre */}
          <div className="mb-8 text-center">
            <p className="text-sm font-semibold tracking-tight">
              CORY
              <span className="text-zinc-500">
                .
              </span>
            </p>

            <h1 className="mt-6 text-3xl font-medium tracking-tight">
              Administration
            </h1>

            <p className="mt-2 text-sm text-zinc-500">
              Accès réservé à l'administrateur.
            </p>
          </div>

          {/* Carte */}
          <div className="rounded-[28px] border border-white/10 bg-white/[0.03] p-7 shadow-2xl backdrop-blur-xl">

            <form
              onSubmit={handleLogin}
              className="space-y-5"
            >

              {/* Identifiant */}
              <div>
                <label className="mb-2 block text-xs uppercase tracking-[0.15em] text-zinc-500">
                  Identifiant
                </label>

                <div className="relative">
                  <User
                    size={18}
                    className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600"
                  />

                  <input
                    type="text"
                    value={username}
                    onChange={(event) =>
                      setUsername(event.target.value)
                    }
                    placeholder="Identifiant"
                    autoComplete="username"
                    className="w-full rounded-2xl border border-white/10 bg-white/[0.03] py-3.5 pl-12 pr-4 text-sm text-white outline-none transition placeholder:text-zinc-700 focus:border-white/25 focus:bg-white/[0.05]"
                  />
                </div>
              </div>

              {/* Mot de passe */}
              <div>
                <label className="mb-2 block text-xs uppercase tracking-[0.15em] text-zinc-500">
                  Mot de passe
                </label>

                <div className="relative">
                  <Lock
                    size={18}
                    className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600"
                  />

                  <input
                    type="password"
                    value={password}
                    onChange={(event) =>
                      setPassword(event.target.value)
                    }
                    placeholder="Mot de passe"
                    autoComplete="current-password"
                    className="w-full rounded-2xl border border-white/10 bg-white/[0.03] py-3.5 pl-12 pr-4 text-sm text-white outline-none transition placeholder:text-zinc-700 focus:border-white/25 focus:bg-white/[0.05]"
                  />
                </div>
              </div>

              {/* Erreur */}
              {error && (
                <motion.div
                  initial={{
                    opacity: 0,
                    y: -5,
                  }}
                  animate={{
                    opacity: 1,
                    y: 0,
                  }}
                  className="rounded-xl border border-red-500/20 bg-red-500/[0.05] px-4 py-3 text-sm text-red-400"
                >
                  {error}
                </motion.div>
              )}

              {/* Bouton */}
              <button
                type="submit"
                className="group flex w-full items-center justify-center gap-2 rounded-2xl bg-white py-3.5 text-sm font-medium text-black transition hover:scale-[1.01] hover:bg-zinc-200 active:scale-[0.99]"
              >
                Se connecter

                <ArrowRight
                  size={17}
                  className="transition-transform duration-300 group-hover:translate-x-1"
                />
              </button>

            </form>
          </div>

          <p className="mt-6 text-center text-xs text-zinc-700">
            Espace privé · Cory Besson
          </p>

        </motion.div>
      </div>
    </main>
  );
}